[CmdletBinding()]
param([string]$AssessmentPath='.\assessments\EVSET-45D-COMPLETE',[string]$FindingsPath='',[string]$OutputPath='.\results',[string]$ReportSuffix='')
Set-StrictMode -Version 2.0;$ErrorActionPreference='Stop'
$assessment=(Resolve-Path -LiteralPath $AssessmentPath).Path;if(!(Test-Path $OutputPath)){New-Item -ItemType Directory -Path $OutputPath -Force|Out-Null}
if([string]::IsNullOrWhiteSpace($FindingsPath)){$fs=if([string]::IsNullOrWhiteSpace($ReportSuffix)){''}else{'_'+$ReportSuffix};$FindingsPath=Join-Path $OutputPath ('DTSX_ANTIPATTERN_PACKAGE_FINDINGS'+$fs+'.csv')}
$runtimePath=Join-Path $assessment '03_runtime\package_runtime_summary.csv';$os=if([string]::IsNullOrWhiteSpace($ReportSuffix)){''}else{'_'+$ReportSuffix};$outPath=Join-Path $OutputPath ('RUNTIME_HEAVY_WITHOUT_ANTIPATTERN'+$os+'.csv')
$findings=@(Import-Csv $FindingsPath);$cols=@('Sort','Aggregate','FuzzyLookup','FastLoadInactive','NoTABLOCK','LookupPartialNoCache','SELECT*','OLEDBCommand','CartesianCrossJoin','NonSargableFunctionPredicate','OnTheFlyFunctionExpression','NestedViewReference','PivotWindowFunction','UnionAll','NoLockAdvisory','MergeJoinComponent','ImplicitConversionIndicator','ScriptComponent','ADO_NET_or_ODBC_Provider','ExplicitBufferOrThreadSetting','TempStoragePathSetting','DestinationCommitSizeSetting','ExecutePackageTask','CheckpointSetting','FullReloadIndicator')
$map=@{};foreach($f in $findings){$key=$f.PackageFile;if($key.StartsWith('SSISDB/')){$key=$key.Substring(7)};$map[$key]=$f}
$heavy=@();foreach($r in (Import-Csv $runtimePath)){if([double]$r.avg_duration_sec -lt 600){continue};$key=('{0}/{1}/{2}'-f $r.folder_name,$r.project_name,$r.package_name);$f=$map[$key];$anti=0;if($f){foreach($c in $cols){$anti += [int]$f.$c}};if($anti -eq 0){$heavy += [pscustomobject]@{folder_name=$r.folder_name;project_name=$r.project_name;package_name=$r.package_name;executions=$r.executions;avg_duration_sec=$r.avg_duration_sec;max_duration_sec=$r.max_duration_sec;failed_or_unexpected=$r.failed_or_unexpected;last_start_time=$r.last_start_time;reason='Average runtime >= 10 minutes, but no static anti-pattern indicator in the selected assessment'}}}
$heavy|Sort-Object {[double]$_.avg_duration_sec}-Descending|Export-Csv $outPath -NoTypeInformation -Encoding UTF8;Write-Host "Wrote $outPath ($(@($heavy).Count) rows); findings source was not modified."
